begin;
drop function reservations.public_registration_recover_family(uuid,text,text,date,bytea,bytea);
create function reservations.public_registration_recover_family(p_public_id uuid,p_full_name text,p_phone text,p_date_of_birth date,p_new_tracking_secret_digest bytea,p_fingerprint_digest bytea) returns jsonb language plpgsql security definer set search_path='' as $$declare v_channel reservations.public_registration_channels%rowtype;v_request reservations.public_registration_requests%rowtype;v_matches integer;begin if nullif(btrim(p_full_name),'') is null or char_length(btrim(p_full_name))>200 or nullif(btrim(p_phone),'') is null or p_date_of_birth is null or p_new_tracking_secret_digest is null or octet_length(p_new_tracking_secret_digest)<>32 then raise exception 'PUBLIC_REGISTRATION_RECOVERY_INVALID' using errcode='22023';end if;select * into v_channel from reservations.public_registration_channels where public_id=p_public_id and enabled for key share;if not found then raise exception 'PUBLIC_REGISTRATION_NOT_FOUND' using errcode='P0002';end if;perform reservations_private.public_registration_rate_limit(v_channel.id,p_fingerprint_digest,8);select count(*) into v_matches from reservations.public_registration_requests where channel_id=v_channel.id and platform_private.person_name_key(submitted_full_name)=platform_private.person_name_key(p_full_name) and platform_private.person_phone_key(submitted_phone)=platform_private.person_phone_key(p_phone) and submitted_date_of_birth=p_date_of_birth;if v_matches<>1 then raise exception 'PUBLIC_REGISTRATION_RECOVERY_NOT_FOUND' using errcode='P0002';end if;select * into v_request from reservations.public_registration_requests where channel_id=v_channel.id and platform_private.person_name_key(submitted_full_name)=platform_private.person_name_key(p_full_name) and platform_private.person_phone_key(submitted_phone)=platform_private.person_phone_key(p_phone) and submitted_date_of_birth=p_date_of_birth for update;update reservations.public_registration_requests set tracking_secret_digest=p_new_tracking_secret_digest,updated_at=statement_timestamp() where id=v_request.id;return jsonb_build_object('reference',v_request.request_reference,'state',v_request.state,'eventId',v_request.event_id);end$$;
revoke all on function reservations.public_registration_recover_family(uuid,text,text,date,bytea,bytea) from public,anon,authenticated,service_role;
do $patch$ declare s text;a text;b text;begin s:=pg_get_functiondef('public.public_registration_gateway(text,jsonb)'::regprocedure);a:='array[''dateOfBirth'',''fingerprintDigest'',''newTrackingSecretDigest'',''phone'',''publicId'',''requestReference'']::text[]';b:='array[''dateOfBirth'',''fingerprintDigest'',''fullName'',''newTrackingSecretDigest'',''phone'',''publicId'']::text[]';if position(a in s)=0 then raise exception 'PUBLIC_REGISTRATION_RECOVERY_GATEWAY_DRIFT';end if;s:=replace(s,a,b);s:=replace(s,'(p_args->>''publicId'')::uuid,p_args->>''requestReference'',p_args->>''phone'',','(p_args->>''publicId'')::uuid,p_args->>''fullName'',p_args->>''phone'',');execute s;end$patch$;
commit;